class TestStateAnalyzer(unittest.TestCase):
    """Tests for StateAnalyzer class."""

    def setUp(self):
        self.analyzer = StateAnalyzer()
        self.test_cwd = os.path.join(os.path.dirname(__file__), "_test_cwd")
        # Create the openspec/changes structure
        self.changes_dir = os.path.join(self.test_cwd, "openspec", "changes")
        self._cleanup()

    def tearDown(self):
        self._cleanup()

    def _cleanup(self):
        """Clean up test directory."""
        if os.path.isdir(self.test_cwd):
            shutil.rmtree(self.test_cwd, ignore_errors=True)

    def _create_change(self, name, has_proposal=False, has_design=False, has_tasks=False, tasks_content=None):
        """Helper to create a test change directory."""
        change_dir = os.path.join(self.changes_dir, name)
        os.makedirs(change_dir, exist_ok=True)
        if has_proposal:
            with open(os.path.join(change_dir, "proposal.md"), "w", encoding="utf-8") as f:
                f.write("# Proposal\n")
        if has_design:
            with open(os.path.join(change_dir, "design.md"), "w", encoding="utf-8") as f:
                f.write("# Design\n")
        if has_tasks:
            with open(os.path.join(change_dir, "tasks.md"), "w", encoding="utf-8") as f:
                f.write(tasks_content or "# Tasks\n")

    # === Task 2.1: StateAnalyzer class ===

    def test_state_analyzer_creation(self):
        """Test StateAnalyzer can be created."""
        analyzer = StateAnalyzer()
        self.assertIsNotNone(analyzer)

    # === Task 2.2: find_active_changes ===

    def test_find_active_changes_empty(self):
        """Test find_active_changes with no changes directory."""
        result = self.analyzer.find_active_changes(self.test_cwd)
        self.assertEqual(result, [])

    def test_find_active_changes_single(self):
        """Test find_active_changes with single change."""
        self._create_change("test-change", has_proposal=True)
        result = self.analyzer.find_active_changes(self.test_cwd)
        self.assertEqual(len(result), 1)
        self.assertEqual(result[0].name, "test-change")

    def test_find_active_changes_multiple(self):
        """Test find_active_changes with multiple changes."""
        self._create_change("change-1", has_proposal=True)
        self._create_change("change-2", has_design=True)
        result = self.analyzer.find_active_changes(self.test_cwd)
        self.assertEqual(len(result), 2)
        names = [c.name for c in result]
        self.assertIn("change-1", names)
        self.assertIn("change-2", names)

    # === Task 2.3: get_change_stage ===

    def test_get_change_stage_proposal(self):
        """Test stage detection for proposal-only change."""
        self._create_change("prop-only", has_proposal=True)
        change_dir = os.path.join(self.changes_dir, "prop-only")
        stage = self.analyzer.get_change_stage(change_dir)
        self.assertEqual(stage, "proposal")

    def test_get_change_stage_design(self):
        """Test stage detection for design stage."""
        self._create_change("design-stage", has_proposal=True, has_design=True)
        change_dir = os.path.join(self.changes_dir, "design-stage")
        stage = self.analyzer.get_change_stage(change_dir)
        self.assertEqual(stage, "design")

    def test_get_change_stage_tasks(self):
        """Test stage detection for tasks stage."""
        self._create_change("tasks-stage", has_proposal=True, has_design=True, has_tasks=True)
        change_dir = os.path.join(self.changes_dir, "tasks-stage")
        stage = self.analyzer.get_change_stage(change_dir)
        self.assertEqual(stage, "tasks")

    # === Task 2.4: get_tasks_progress ===

    def test_get_tasks_progress_no_tasks(self):
        """Test progress when no tasks.md exists."""
        self._create_change("no-tasks", has_proposal=True)
        change_dir = os.path.join(self.changes_dir, "no-tasks")
        total, done = self.analyzer.get_tasks_progress(change_dir)
        self.assertEqual(total, 0)
        self.assertEqual(done, 0)

    def test_get_tasks_progress_partial(self):
        """Test progress with partial completion."""
        tasks = "# Tasks\n- [ ] Task 1\n- [x] Task 2\n- [ ] Task 3\n"
        self._create_change("partial-tasks", has_tasks=True, tasks_content=tasks)
        change_dir = os.path.join(self.changes_dir, "partial-tasks")
        total, done = self.analyzer.get_tasks_progress(change_dir)
        self.assertEqual(total, 3)
        self.assertEqual(done, 1)

    def test_get_tasks_progress_complete(self):
        """Test progress with all tasks complete."""
        tasks = "# Tasks\n- [x] Task 1\n- [x] Task 2\n- [x] Task 3\n"
        self._create_change("complete-tasks", has_tasks=True, tasks_content=tasks)
        change_dir = os.path.join(self.changes_dir, "complete-tasks")
        total, done = self.analyzer.get_tasks_progress(change_dir)
        self.assertEqual(total, 3)
        self.assertEqual(done, 3)


