class TestIntentClassifier(unittest.TestCase):
    """Tests for IntentClassifier class."""

    def setUp(self):
        self.classifier = IntentClassifier()

    # === Task 1.1: Intent patterns ===

    def test_explore_intent_detection(self):
        """Test explore intent detection."""
        result = self.classifier.detect("分析这个模块的结构")
        self.assertEqual(result.intent_type, "explore")

        result = self.classifier.detect("understand the code flow")
        self.assertEqual(result.intent_type, "explore")

    def test_implement_intent_detection(self):
        """Test implement intent detection."""
        result = self.classifier.detect("实现一个新功能")
        self.assertEqual(result.intent_type, "implement")

        result = self.classifier.detect("add a new feature for login")
        self.assertEqual(result.intent_type, "implement")

    def test_fix_intent_detection(self):
        """Test fix intent detection."""
        result = self.classifier.detect("修复这个bug")
        self.assertEqual(result.intent_type, "fix")

        result = self.classifier.detect("fix the null pointer issue")
        self.assertEqual(result.intent_type, "fix")

    def test_archive_intent_detection(self):
        """Test archive intent detection."""
        result = self.classifier.detect("归档这个变更")
        self.assertEqual(result.intent_type, "archive")

        result = self.classifier.detect("finish the implementation")
        self.assertEqual(result.intent_type, "archive")

    def test_question_intent_detection(self):
        """Test question intent detection."""
        result = self.classifier.detect("这个函数是什么意思？")
        self.assertEqual(result.intent_type, "question")

        result = self.classifier.detect("what does this function do?")
        self.assertEqual(result.intent_type, "question")

    # === Task 1.2: Keyword matching with regex ===

    def test_chinese_keyword_matching(self):
        """Test Chinese keyword matching."""
        result = self.classifier.detect("实现添加新功能")
        self.assertEqual(result.intent_type, "implement")
        self.assertGreaterEqual(len(result.matched_keywords), 2)

    def test_english_keyword_matching(self):
        """Test English keyword matching."""
        result = self.classifier.detect("implement and add new feature")
        self.assertEqual(result.intent_type, "implement")
        self.assertGreaterEqual(len(result.matched_keywords), 2)

    def test_mixed_language_matching(self):
        """Test mixed Chinese and English keywords."""
        result = self.classifier.detect("implement 新功能")
        self.assertEqual(result.intent_type, "implement")

    # === Task 1.3: Confidence level calculation ===

    def test_high_confidence_with_multiple_matches(self):
        """Test high confidence when 2+ keyword matches."""
        result = self.classifier.detect("实现添加新功能开发")
        self.assertEqual(result.confidence, "high")

    def test_medium_confidence_with_one_match(self):
        """Test medium confidence when 1 keyword match."""
        result = self.classifier.detect("实现一个功能")
        self.assertEqual(result.confidence, "medium")

    def test_low_confidence_no_match(self):
        """Test low confidence when no keywords match."""
        result = self.classifier.detect("random text without keywords")
        self.assertEqual(result.confidence, "low")
        self.assertEqual(result.intent_type, "question")  # Default fallback

    # === Task 1.4-1.5: Scope estimation ===

    def test_trivial_scope_detection(self):
        """Test trivial scope detection."""
        result = self.classifier.detect("修复typo拼写错误")
        self.assertEqual(result.scope, "trivial")

    def test_small_scope_detection(self):
        """Test small scope detection."""
        result = self.classifier.detect("添加一个简单的函数")
        self.assertEqual(result.scope, "small")

    def test_medium_scope_detection(self):
        """Test medium scope detection (default)."""
        result = self.classifier.detect("实现一个功能")
        self.assertEqual(result.scope, "medium")

    def test_large_scope_detection(self):
        """Test large scope detection."""
        result = self.classifier.detect("重构整个系统架构")
        self.assertEqual(result.scope, "large")

    # === Task 1.6: Trivial fix heuristics ===

    def test_trivial_fix_scope_trivial(self):
        """Test trivial fix detection when scope is trivial."""
        result = self.classifier.detect("修复typo")
        self.assertTrue(result.is_trivial_fix)

    def test_trivial_fix_private_keyword(self):
        """Test trivial fix detection with private keywords."""
        result = self.classifier.detect("修复内部helper函数")
        self.assertTrue(result.is_trivial_fix)

    def test_non_trivial_fix(self):
        """Test non-trivial fix detection."""
        result = self.classifier.detect("实现大型重构")
        # No trivial hints, scope is large, not a fix
        self.assertFalse(result.is_trivial_fix)


