class TestOutputBuilder(unittest.TestCase):
    """Tests for OutputBuilder class."""

    def setUp(self):
        self.builder = OutputBuilder()

    def _make_intent(
        self,
        intent_type="implement",
        confidence="high",
        scope="medium",
        is_trivial_fix=False
    ):
        """Helper to create IntentResult."""
        return IntentResult(
            intent_type=intent_type,
            confidence=confidence,
            scope=scope,
            is_trivial_fix=is_trivial_fix,
            matched_keywords=[]
        )

    def _make_decision(
        self,
        action="explore",
        mode="auto",
        reason="test reason",
        options=None
    ):
        """Helper to create RouteDecision."""
        return RouteDecision(
            action=action,
            mode=mode,
            reason=reason,
            options=options or []
        )

    def _make_change(
        self,
        name="test-change",
        stage="tasks",
        tasks_total=5,
        tasks_done=0
    ):
        """Helper to create ChangeInfo."""
        return ChangeInfo(
            name=name,
            path="/path/to/change",
            stage=stage,
            tasks_total=tasks_total,
            tasks_done=tasks_done
        )

    # === Task 4.1: OutputBuilder class ===

    def test_output_builder_creation(self):
        """Test OutputBuilder can be created."""
        builder = OutputBuilder()
        self.assertIsNotNone(builder)

    # === Task 4.2: auto_route format ===

    def test_auto_route_explore(self):
        """Test auto-route format for explore."""
        decision = self._make_decision(action="explore", reason="Test reason")
        output = self.builder.auto_route(decision)
        self.assertIn("Auto-Route: /openspec-explore", output)
        self.assertIn("Reason: Test reason", output)

    def test_auto_route_apply_change(self):
        """Test auto-route format for apply-change."""
        decision = self._make_decision(action="apply-change", reason="Continuing work")
        output = self.builder.auto_route(decision)
        self.assertIn("Auto-Route: /openspec-apply-change", output)

    def test_auto_route_archive(self):
        """Test auto-route format for archive."""
        decision = self._make_decision(action="archive", reason="All complete")
        output = self.builder.auto_route(decision)
        self.assertIn("Auto-Route: /openspec-archive-change", output)

    def test_auto_route_direct(self):
        """Test auto-route format for direct (no skill)."""
        decision = self._make_decision(action="direct", reason="Direct action")
        output = self.builder.auto_route(decision)
        self.assertIn("Direct action", output)
        self.assertNotIn("Auto-Route:", output)

    # === Task 4.3: suggestion format ===

    def test_suggestion_with_options(self):
        """Test suggestion format with options."""
        intent = self._make_intent(intent_type="implement")
        decision = self._make_decision(
            action="explore",
            mode="suggest",
            reason="No active change",
            options=["Option 1", "Option 2"]
        )
        output = self.builder.suggestion(intent, [], decision)
        self.assertIn("Detected intent: **implement**", output)
        self.assertIn("Reason: No active change", output)
        self.assertIn("1. Option 1", output)
        self.assertIn("2. Option 2", output)

    # === Task 4.4: direct format ===

    def test_direct_empty_changes(self):
        """Test direct format with no changes."""
        output = self.builder.direct([])
        self.assertEqual(output, "")

    def test_direct_with_change(self):
        """Test direct format with active change."""
        change = self._make_change(name="test-change", tasks_total=5, tasks_done=2)
        output = self.builder.direct([change])
        self.assertIn("=== OpenSpec Active Changes Detected ===", output)
        self.assertIn("Change: test-change", output)
        self.assertIn("=== Instructions ===", output)

    def test_direct_with_complete_change(self):
        """Test direct format with complete change includes auto-commit."""
        change = self._make_change(name="complete-change", tasks_total=5, tasks_done=5)
        output = self.builder.direct([change])
        self.assertIn("=== Auto-Commit:", output)
        self.assertIn("All 5 tasks", output)

    # === Task 4.5: Preserve existing behavior ===

    def test_direct_preserves_change_info(self):
        """Test direct format preserves change info structure."""
        change = self._make_change(name="my-change", tasks_total=10, tasks_done=3)
        output = self.builder.direct([change])
        # Check structure matches existing behavior
        self.assertIn("Change: my-change", output)
        self.assertIn("Before responding to the user's question:", output)


class TestMainIntegration(unittest.TestCase):
    """Integration tests for main() function (Tasks 5.1-5.4)."""

    # === Task 5.4: Test with various prompt types ===

    def test_implement_intent_routes_correctly(self):
        """Test implement intent produces appropriate routing."""
        classifier = IntentClassifier()
        intent = classifier.detect("实现一个新功能")
        router = Router()
        decision = router.decide(intent, [])

        # Should suggest explore when no active change
        self.assertEqual(decision.action, "explore")

    def test_fix_trivial_routes_directly(self):
        """Test trivial fix routes to direct."""
        classifier = IntentClassifier()
        # Use multiple fix keywords for high confidence: 修复 + 解决
        intent = classifier.detect("修复解决typo拼写错误")
        router = Router()
        decision = router.decide(intent, [])

        # Trivial fix with high confidence should auto-route to direct
        self.assertEqual(decision.action, "direct")
        self.assertEqual(decision.mode, "auto")

    def test_question_routes_directly(self):
        """Test question intent routes directly."""
        classifier = IntentClassifier()
        intent = classifier.detect("这个函数是什么？")
        router = Router()
        decision = router.decide(intent, [])

        self.assertEqual(decision.action, "direct")
